return msg;

const parts = msg.topic.split('/');
const requestId = parts[parts.length - 1];

msg.rpcRequestId = requestId;
msg.rpcResponseTopic = 'v1/devices/me/rpc/response/' + requestId;

const rpc = msg.payload || {};

msg.rpcMethod = rpc.method;
msg.rpcParams = rpc.params || {};

// Only handle getTotalEnergyFlowState
if (msg.rpcMethod !== 'getTotalEnergyFlowState') {
    return null;
}

msg.isRpcRequest = true;
return msg;

const parts = msg.topic.split('/');
const requestId = parts[parts.length - 1];

msg.rpcRequestId = requestId;
msg.rpcResponseTopic = 'v1/devices/me/rpc/response/' + requestId;

const rpc = msg.payload || {};

msg.rpcMethod = rpc.method;
msg.rpcParams = rpc.params || {};

if (msg.rpcMethod === 'getSystemWorkModeConfig') {
    msg.isRpcRequest = true;
    msg.operationType = 'read';
    return msg;
}
else if (msg.rpcMethod === 'setSystemWorkModeConfig') {
    msg.isRpcRequest = true;
    msg.operationType = 'write';
    return msg;
}
else {
    return null;
}

// Read all capacity-related registers in parallel
const reads = [
    { name: 'deviceType', address: 100, quantity: 1 },
    { name: 'ratedPower', address: 120, quantity: 2 },  // 32-bit
    { name: 'batteryCapacity', address: 202, quantity: 1 },
    { name: 'batteryMode', address: 211, quantity: 1 },
    { name: 'batterySoc', address: 688, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name
}));

return [messages];

const flowKey = 'scs_reads';
let collected = flow.get(flowKey) || {};
let expectedCount = 5;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const readName = msg.readName;

// Store the data based on type
if (readName === 'ratedPower') {
    // 32-bit value (2 registers)
    collected[readName] = data;
} else {
    // Single register reads
    collected[readName] = data[0];
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

// Build SystemCapacityState from Modbus reads

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const serialNumber = global.get("INVERTER_SN") || "Unknown";

// Parse device type
const deviceType = data.deviceType;

// Parse rated power (32-bit: high word << 16 | low word)
const ratedPowerRaw = (data.ratedPower[1] << 16) | data.ratedPower[0];
const ratedPowerW = ratedPowerRaw / 10;  // 0.1W scale
const ratedPowerKw = ratedPowerW / 1000;

// Parse battery data
const capacityAh = data.batteryCapacity;
const socPercent = data.batterySoc;
const controlMode = data.batteryMode;

// Assume nominal voltage (typical for LFP batteries)
const nominalVoltageV = 51.2;  // Standard LFP voltage
const capacityKwh = (capacityAh * nominalVoltageV) / 1000;

// Build state object
const state = {
    kind: "SystemCapacityState",
    version: 1,
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: serialNumber,

    inverter: {
        deviceType: deviceType,
        ratedPowerW: ratedPowerW,
        ratedPowerKw: ratedPowerKw
    },

    battery: {
        capacityAh: capacityAh,
        nominalVoltageV: nominalVoltageV,
        capacityKwh: capacityKwh,
        socPercent: socPercent,
        controlMode: controlMode
    },

    rawRegisters: {
        reg100: deviceType,
        reg120: data.ratedPower[0],
        reg121: data.ratedPower[1],
        reg202: capacityAh,
        reg211: controlMode,
        reg688: socPercent
    }
};

// Create a hash for change detection
const stateHash = JSON.stringify({
    deviceType: deviceType,
    ratedPowerW: ratedPowerW,
    capacityAh: capacityAh,
    socPercent: socPercent,
    controlMode: controlMode
});

msg.currentStateHash = stateHash;
msg.previousStateHash = flow.get("lastCapacityStateHash");

// Update stored hash
flow.set("lastCapacityStateHash", stateHash);

msg.payload = state;
msg.state = state;

node.status({ fill: "green", shape: "dot", text: `${ratedPowerKw}kW / ${capacityAh}Ah (${socPercent}%)` });

return msg;

// Check if capacity state has changed
// RPC requests always get response
// Periodic polls only send to ThingsBoard if value changed

const currentHash = msg.currentStateHash;
const previousHash = msg.previousStateHash;
const isRpc = msg.isRpcRequest === true;

// Determine if state changed
const stateChanged = (previousHash === undefined || previousHash === null || currentHash !== previousHash);

msg.stateChanged = stateChanged;

// Debug status
if (stateChanged) {
    node.status({ fill: "green", shape: "dot", text: "State changed - sending to TB" });
} else {
    node.status({ fill: "grey", shape: "ring", text: "No change" });
}

// Output routing:
// Output 1: Debug (always)
// Output 2: MQTT ThingsBoard (only if changed)
// Output 3: RPC Response (only if RPC request)

const debugMsg = { ...msg };
const mqttMsg = stateChanged ? { ...msg } : null;
const rpcMsg = isRpc ? { ...msg } : null;

return [debugMsg, mqttMsg, rpcMsg];

// Only respond if this came from RPC
if (!msg.rpcResponseTopic) {
    return null;
}

const state = msg.state || msg.payload;

msg.payload = state;
msg.topic = msg.rpcResponseTopic;

return msg;

// Battery SOC
// 688: Battery capacity %

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 688,
    quantity: 1
};
return msg;

// Build BatterySocState from Modbus read.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

const socPercent = data[0] || 0;  // 688: Battery capacity %

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "BatterySocState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    inverterBatChannelSoc: [
        {
            channelId: 1,
            socPercent: socPercent
        },
        {
            channelId: 2,
            socPercent: null  // Three-phase only has 1 channel
        }
    ],

    bmsSocDetails: null  // Not available in three-phase datasheet
};

// Store current SOC for change detection
msg.currentSocPercent = socPercent;

// Get previous SOC value
msg.previousSocPercent = flow.get("lastSocPercent");

// Update stored value
flow.set("lastSocPercent", socPercent);

// Store snapshot
flow.set("batterySocStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

// Check if SOC value has changed
// RPC requests always get response
// Periodic polls only send to ThingsBoard if value changed

const currentSoc = msg.currentSocPercent;
const previousSoc = msg.previousSocPercent;
const isRpc = msg.isRpcRequest === true;

// Determine if SOC changed
// First read (previousSoc undefined/null) counts as changed
const socChanged = (previousSoc === undefined || previousSoc === null || currentSoc !== previousSoc);

msg.socChanged = socChanged;

// Debug status
if (socChanged) {
    node.status({ fill: "green", shape: "dot", text: `SOC: ${currentSoc}% (changed from ${previousSoc || 'N/A'}%)` });
} else {
    node.status({ fill: "grey", shape: "ring", text: `SOC: ${currentSoc}% (no change)` });
}

// Output routing:
// Output 1: Debug (always)
// Output 2: MQTT ThingsBoard (only if changed)
// Output 3: RPC Response (only if RPC request)

const debugMsg = { ...msg };
const mqttMsg = socChanged ? { ...msg } : null;
const rpcMsg = isRpc ? { ...msg } : null;

return [debugMsg, mqttMsg, rpcMsg];

// Only respond if this came from RPC
if (!msg.rpcResponseTopic) {
    return null;
}

const state = msg.state || msg.payload;

msg.payload = state;
msg.topic = msg.rpcResponseTopic;

return msg;

// Store RPC response topic if present
if (msg.rpcResponseTopic) {
    flow.set("def_rpc_response_topic", msg.rpcResponseTopic);
}

// Battery daily energy
// 614: Today charge (0.1kWh)
// 615: Today discharge (0.1kWh)

msg.baseAddr = 614;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 614,
    quantity: 2  // 614-615
};
return msg;

// Grid daily energy
// 620: Day_GridBuy_Power (0.1kWh)
// 621: Day_GridSell_Power (0.1kWh)

msg.baseAddr = 620;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 620,
    quantity: 2  // 620-621
};
return msg;

// Load, PV, Generator daily energy
// 626: Day_Load_Power (0.1kWh)
// 627-628: (skip)
// 629: Day_PV_Power (0.1kWh)
// 630-635: (skip)
// 636: Generator daily (0.1kWh)

msg.baseAddr = 626;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 626,
    quantity: 11  // 626-636
};
return msg;

const base = msg.baseAddr;
const data = msg.payload.data || msg.payload;

// Store partial results in flow context
if (base === 614) {
    // Battery: 614-615
    flow.set("def_battery", {
        chargeEnergyKWh: data[0] * 0.1,      // 614
        dischargeEnergyKWh: data[1] * 0.1    // 615
    });
}
else if (base === 620) {
    // Grid: 620-621
    flow.set("def_grid", {
        importEnergyKWh: data[0] * 0.1,      // 620
        exportEnergyKWh: data[1] * 0.1       // 621
    });
}
else if (base === 626) {
    // Load/PV/Gen: 626, 629, 636
    flow.set("def_load", data[0] * 0.1);                    // 626
    flow.set("def_pv", data[3] * 0.1);                      // 629 (offset 3)
    flow.set("def_generator", data[10] * 0.1);              // 636 (offset 10)
}

// Check if all parts are ready
const battery = flow.get("def_battery");
const grid = flow.get("def_grid");
const load = flow.get("def_load");
const pv = flow.get("def_pv");
const generator = flow.get("def_generator");

if (!battery || !grid || load === undefined || pv === undefined || generator === undefined) {
    return null;  // Wait for all parts
}

// All data collected, build final JSON
const result = {
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: "EC100",

    loadEnergyKWh: load,

    grid: {
        importEnergyKWh: grid.importEnergyKWh,
        exportEnergyKWh: grid.exportEnergyKWh
    },

    pv: {
        totalEnergyKWh: pv,
        mppt: [
            { id: 1, energyKWh: null },  // Not available in datasheet
            { id: 2, energyKWh: null },
            { id: 3, energyKWh: null },
            { id: 4, energyKWh: null }
        ]
    },

    battery: {
        chargeEnergyKWh: battery.chargeEnergyKWh,
        dischargeEnergyKWh: battery.dischargeEnergyKWh
    },

    generator: {
        energyKWh: generator
    }
};

// Clear flow context
flow.set("def_battery", null);
flow.set("def_grid", null);
flow.set("def_load", null);
flow.set("def_pv", null);
flow.set("def_generator", null);

// Check if this is an RPC request
const rpcTopic = flow.get("def_rpc_response_topic");
if (rpcTopic) {
    // Send RPC response
    msg.payload = { success: true, data: result };
    msg.topic = rpcTopic;
    flow.set("def_rpc_response_topic", null);
    return [msg, null];
} else {
    // Send telemetry
    msg.payload = result;
    return [null, msg];
}

// Store RPC response topic if present
if (msg.rpcResponseTopic) {
    flow.set("gds_rpc_response_topic", msg.rpcResponseTopic);
    msg.isRpcRequest = true;
}

// Historical accumulated runtime
// 612 (low) + 613 (high): Generator historical runtime (0.1h, S32)

msg.baseAddr = 612;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 612,
    quantity: 2
};
return msg;

// Generator energy - today and total
// 636: Generator daily (0.1kWh)
// 637 (low) + 638 (high): Generator total energy (0.1kWh)

msg.baseAddr = 636;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 636,
    quantity: 3  // 636-638
};
return msg;

// Generator daily runtime
// 639: Generator daily runtime (0.1h)

msg.baseAddr = 639;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 639,
    quantity: 1
};
return msg;

// Generator frequency
// 709: Grid-side frequency (0.01Hz)

msg.baseAddr = 709;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 709,
    quantity: 1
};
return msg;

// Generator phase voltages
// 761: Gen port phase voltage A (0.1V)
// 762: Gen port phase voltage B (0.1V)
// 763: Gen port phase voltage C (0.1V)

msg.baseAddr = 761;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 761,
    quantity: 3  // 761-763
};
return msg;

// Generator phase powers (S32)
// 764 (low) + 768 (high): Gen port phase A power (1W, S32)
// 765 (low) + 769 (high): Gen port phase B power (1W, S32)
// 766 (low) + 770 (high): Gen port phase C power (1W, S32)
// 767 (low) + 771 (high): Gen port total power (1W, S32)

msg.baseAddr = 764;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 764,
    quantity: 8  // 764-771
};
return msg;

// Build GeneratorDeviceState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("GeneratorDeviceState: missing base address");
    return null;
}

// Helper: signed 16-bit
function s16(v) {
    if (!Number.isFinite(v)) return 0;
    return (v & 0x8000) ? v - 0x10000 : v;
}

// Helper: combine two 16-bit words to 32-bit signed
function s32(low, high) {
    const u = ((high & 0xFFFF) << 16) | (low & 0xFFFF);
    return (u & 0x80000000) ? u - 0x100000000 : u;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// ---- Store partials ----

// Historical Runtime 612-613
if (baseAddr === 612) {
    const histLow = data[0] || 0;
    const histHigh = data[1] || 0;
    const histRuntime = u32(histLow, histHigh) * 0.1;
    flow.set("gds_part_runtime_hist", {
        accumulatedRunTimeHours: Math.round(histRuntime * 10) / 10
    });
}

// Energy 636-638
else if (baseAddr === 636) {
    const todayEnergy = data[0] || 0;       // 636
    const totalLow = data[1] || 0;          // 637
    const totalHigh = data[2] || 0;         // 638
    const totalEnergy = u32(totalLow, totalHigh) * 0.1;

    flow.set("gds_part_energy", {
        todayGenEnergyKWh: Math.round(todayEnergy * 0.1 * 100) / 100,
        totalGenEnergyKWh: Math.round(totalEnergy * 100) / 100
    });
}

// Daily Runtime 639
else if (baseAddr === 639) {
    const dailyRuntime = data[0] || 0;  // 0.1h
    flow.set("gds_part_daily_runtime", {
        dailyRunTimeHours: Math.round(dailyRuntime * 0.1 * 10) / 10
    });
}

// Frequency 709
else if (baseAddr === 709) {
    const freqRaw = data[0] || 0;  // 0.01Hz
    flow.set("gds_part_freq", {
        genFrequencyHz: Math.round(freqRaw * 0.01 * 100) / 100
    });
}

// Voltage 761-763
else if (baseAddr === 761) {
    const vA = data[0] || 0;  // 0.1V
    const vB = data[1] || 0;
    const vC = data[2] || 0;

    flow.set("gds_part_voltage", {
        phaseAVoltageV: Math.round(vA * 0.1 * 10) / 10,
        phaseBVoltageV: Math.round(vB * 0.1 * 10) / 10,
        phaseCVoltageV: Math.round(vC * 0.1 * 10) / 10
    });
}

// Power 764-771 (S32 values)
else if (baseAddr === 764) {
    // Phase A: 764 (low) + 768 (high)
    // Phase B: 765 (low) + 769 (high)
    // Phase C: 766 (low) + 770 (high)
    // Total:   767 (low) + 771 (high)

    const pA = s32(data[0], data[4]);  // 764 + 768
    const pB = s32(data[1], data[5]);  // 765 + 769
    const pC = s32(data[2], data[6]);  // 766 + 770
    const pTotal = s32(data[3], data[7]);  // 767 + 771

    flow.set("gds_part_power", {
        phaseAPowerW: pA,
        phaseBPowerW: pB,
        phaseCPowerW: pC,
        totalPowerW: pTotal,
        smartLoadActivePowerW: pTotal  // Same as total when in smart load mode
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const runtimeHistPart = flow.get("gds_part_runtime_hist");
const energyPart = flow.get("gds_part_energy");
const dailyRuntimePart = flow.get("gds_part_daily_runtime");
const freqPart = flow.get("gds_part_freq");
const voltagePart = flow.get("gds_part_voltage");
const powerPart = flow.get("gds_part_power");

if (!runtimeHistPart || !energyPart || !dailyRuntimePart || !freqPart || !voltagePart || !powerPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100";

const state = {
    kind: "GeneratorDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    genVoltage: {
        phaseAVoltageV: voltagePart.phaseAVoltageV,
        phaseBVoltageV: voltagePart.phaseBVoltageV,
        phaseCVoltageV: voltagePart.phaseCVoltageV
    },

    genFrequencyHz: freqPart.genFrequencyHz,

    genPower: {
        phaseAPowerW: powerPart.phaseAPowerW,
        phaseBPowerW: powerPart.phaseBPowerW,
        phaseCPowerW: powerPart.phaseCPowerW,
        totalPowerW: powerPart.totalPowerW
    },

    smartLoadActivePowerW: powerPart.smartLoadActivePowerW,
    todayGenEnergyKWh: energyPart.todayGenEnergyKWh,
    dailyRunTimeHours: dailyRuntimePart.dailyRunTimeHours,
    totalGenEnergyKWh: energyPart.totalGenEnergyKWh,
    accumulatedRunTimeHours: runtimeHistPart.accumulatedRunTimeHours
};

// Clear partials
flow.set("gds_part_runtime_hist", null);
flow.set("gds_part_energy", null);
flow.set("gds_part_daily_runtime", null);
flow.set("gds_part_freq", null);
flow.set("gds_part_voltage", null);
flow.set("gds_part_power", null);

flow.set("generatorDeviceStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

// Check if generator is active or if this is an RPC request
// Only send to ThingsBoard telemetry if:
// 1. Generator has power (totalPowerW != 0)
// 2. OR Generator has voltage (any phase > 0)
// 3. OR Generator has frequency (genFrequencyHz > 0)
// 4. OR This is an RPC request (always respond)

const state = msg.payload;
const isRpcRequest = msg.isRpcRequest === true;

const hasPower = state.genPower.totalPowerW !== 0;
const hasVoltage = state.genVoltage.phaseAVoltageV > 2 
    || state.genVoltage.phaseBVoltageV > 2 
    || state.genVoltage.phaseCVoltageV > 2;
const hasFrequency = state.genFrequencyHz > 0;
const isGeneratorActive = hasPower || hasVoltage || hasFrequency;

// RPC requests always get a response
if (isRpcRequest) {
    node.status({ 
        fill: "blue", 
        shape: "dot", 
        text: `RPC response - ${state.genPower.totalPowerW}W` 
    });
    return [msg, msg];  // Send to both telemetry and RPC response
}

// Periodic poll - only send if generator is active
if (!isGeneratorActive) {
    // Check if we need to send "generator stopped" once
    const previousWasActive = flow.get("gds_previous_was_active") || false;

    if (previousWasActive) {
        // Send one "stopped" message
        flow.set("gds_previous_was_active", false);
        node.status({ fill: "grey", shape: "dot", text: "Stopped - sent" });
        return [msg, null];  // Send to telemetry only
    } else {
        // Already sent stopped, don't spam
        node.status({ fill: "grey", shape: "ring", text: "Inactive - skipped" });
        return [null, null];
    }
}

// Generator is active - send it
flow.set("gds_previous_was_active", true);

node.status({ 
    fill: "green", 
    shape: "dot", 
    text: `Active - ${state.genPower.totalPowerW}W` 
});

return [msg, null];  // Send to telemetry only

// Only handle messages that came from RPC
const rpcTopic = flow.get("gds_rpc_response_topic");
if (!rpcTopic) {
    return null;
}

const state = msg.state || msg.payload;

msg.payload = { success: true, data: state };
msg.topic = rpcTopic;

flow.set("gds_rpc_response_topic", null);

return msg;

// Run state
// 600: 0=standby, 1=selfcheck, 2=normal, 3=alarm, 4=fault

msg.baseAddr = 600;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 600,
    quantity: 1
};
return msg;

// Warning and Fault words
// 653: Warning message word 1
// 654: Warning message word 2
// 655: Fault information word 1
// 656: Fault information word 2
// 657: Fault information word 3
// 658: Fault information word 4

msg.baseAddr = 653;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 653,
    quantity: 6  // 653-658
};
return msg;

// Build InverterAlarmState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("InverterAlarmState: missing base address");
    return null;
}

// ---- Store partials ----

// RunState 600
if (baseAddr === 600) {
    flow.set("ias_part_runstate", {
        runStateRaw: data[0] || 0
    });
}

// Warnings/Faults 653-658
else if (baseAddr === 653) {
    flow.set("ias_part_warnings_faults", {
        warningWord1Raw: data[0] || 0,   // 653
        warningWord2Raw: data[1] || 0,   // 654
        faultWord1Raw: data[2] || 0,     // 655
        faultWord2Raw: data[3] || 0,     // 656
        faultWord3Raw: data[4] || 0,     // 657
        faultWord4Raw: data[5] || 0      // 658
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const runstatePart = flow.get("ias_part_runstate");
const warningsFaultsPart = flow.get("ias_part_warnings_faults");

if (!runstatePart || !warningsFaultsPart) {
    return null;
}

const gatewayId = msg.gatewayId
    || global.get("GATEWAY_ID")
    || env.get("GATEWAY_ID")
    || "EC100";

const inverterSerial = msg.inverterSerialNumber
    || global.get("INVERTER_SERIAL")
    || env.get("INVERTER_SERIAL")
    || "Unknown";

// Decode active alarms from fault/warning words
const activeAlarms = [];
const now = new Date().toISOString();

// Three-phase Fault Word 1 (655) bit definitions
const faultWord1Bits = {
    0: { code: 1001, severity: "fault", sourceDevice: "inverter", category: "dc_voltage", messageKey: "DC_VOLTAGE_HIGH" },
    1: { code: 1002, severity: "fault", sourceDevice: "inverter", category: "dc_voltage", messageKey: "BUS_VOLTAGE_HIGH" },
    2: { code: 1003, severity: "fault", sourceDevice: "inverter", category: "dc_voltage", messageKey: "BUS_VOLTAGE_LOW" },
    3: { code: 1004, severity: "fault", sourceDevice: "inverter", category: "dc_voltage", messageKey: "BUS_VOLTAGE_UNBALANCED" },
    4: { code: 1005, severity: "fault", sourceDevice: "grid", category: "ac_voltage", messageKey: "GRID_VOLTAGE_HIGH" },
    5: { code: 1006, severity: "fault", sourceDevice: "grid", category: "ac_voltage", messageKey: "GRID_VOLTAGE_LOW" },
    6: { code: 1007, severity: "fault", sourceDevice: "grid", category: "frequency", messageKey: "GRID_FREQ_HIGH" },
    7: { code: 1008, severity: "fault", sourceDevice: "grid", category: "frequency", messageKey: "GRID_FREQ_LOW" },
    8: { code: 1009, severity: "fault", sourceDevice: "grid", category: "connection", messageKey: "GRID_DISCONNECT" },
    9: { code: 1010, severity: "fault", sourceDevice: "inverter", category: "current", messageKey: "OUTPUT_CURRENT_HIGH" },
    10: { code: 1011, severity: "fault", sourceDevice: "inverter", category: "over_temp", messageKey: "INVERTER_OVER_TEMP" },
    11: { code: 1012, severity: "fault", sourceDevice: "inverter", category: "leakage", messageKey: "LEAKAGE_CURRENT_HIGH" },
    12: { code: 1013, severity: "fault", sourceDevice: "inverter", category: "hardware", messageKey: "HARDWARE_FAULT" },
    13: { code: 1014, severity: "fault", sourceDevice: "inverter", category: "communication", messageKey: "EEPROM_FAULT" },
    14: { code: 1015, severity: "fault", sourceDevice: "inverter", category: "relay", messageKey: "RELAY_FAULT" },
    15: { code: 1016, severity: "fault", sourceDevice: "inverter", category: "hardware", messageKey: "DSP_FAULT" }
};

// Three-phase Warning Word 1 (653) bit definitions
const warningWord1Bits = {
    0: { code: 2001, severity: "warning", sourceDevice: "battery", category: "voltage", messageKey: "BATTERY_VOLTAGE_HIGH" },
    1: { code: 2002, severity: "warning", sourceDevice: "battery", category: "voltage", messageKey: "BATTERY_VOLTAGE_LOW" },
    2: { code: 2003, severity: "warning", sourceDevice: "battery", category: "communication", messageKey: "BATTERY_COMM_FAIL" },
    3: { code: 2004, severity: "warning", sourceDevice: "inverter", category: "over_temp", messageKey: "INVERTER_TEMP_HIGH" },
    4: { code: 2005, severity: "warning", sourceDevice: "pv", category: "voltage", messageKey: "PV_VOLTAGE_HIGH" },
    5: { code: 2006, severity: "warning", sourceDevice: "inverter", category: "fan", messageKey: "FAN_LOCKED" },
    6: { code: 2007, severity: "warning", sourceDevice: "grid", category: "power", messageKey: "FEED_IN_POWER_LIMIT" },
    7: { code: 2008, severity: "warning", sourceDevice: "inverter", category: "firmware", messageKey: "FIRMWARE_UPDATE" },
    8: { code: 2009, severity: "warning", sourceDevice: "grid", category: "phase_balance", messageKey: "PHASE_IMBALANCE" },
    9: { code: 2010, severity: "warning", sourceDevice: "inverter", category: "phase_voltage", messageKey: "PHASE_VOLTAGE_UNBALANCED" }
};

// Decode fault bits
function decodeBits(word, bitDefs) {
    const alarms = [];
    for (let bit = 0; bit < 16; bit++) {
        if ((word & (1 << bit)) !== 0 && bitDefs[bit]) {
            const def = bitDefs[bit];
            alarms.push({
                code: def.code,
                vendorCode: bit,
                severity: def.severity,
                sourceDevice: def.sourceDevice,
                category: def.category,
                messageKey: def.messageKey,
                messageParams: {},
                firstOccurredUtc: now,
                lastOccurredUtc: now,
                occurrenceCount: 1
            });
        }
    }
    return alarms;
}

// Decode all words
activeAlarms.push(...decodeBits(warningsFaultsPart.faultWord1Raw, faultWord1Bits));
activeAlarms.push(...decodeBits(warningsFaultsPart.warningWord1Raw, warningWord1Bits));
// Add more decoders for faultWord2-4, warningWord2 as needed

const state = {
    kind: "InverterAlarmState",
    timestampUtc: now,
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSerial,

    runStateRaw: runstatePart.runStateRaw,
    warningWord1Raw: warningsFaultsPart.warningWord1Raw,
    warningWord2Raw: warningsFaultsPart.warningWord2Raw,
    faultWord1Raw: warningsFaultsPart.faultWord1Raw,
    faultWord2Raw: warningsFaultsPart.faultWord2Raw,
    faultWord3Raw: warningsFaultsPart.faultWord3Raw,
    faultWord4Raw: warningsFaultsPart.faultWord4Raw,

    activeAlarms: activeAlarms
};

// Clear partials
flow.set("ias_part_runstate", null);
flow.set("ias_part_warnings_faults", null);

flow.set("inverterAlarmStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

// Only send to ThingsBoard if there's an actual problem:
// 1. runState != 2 (not normal)
// 2. OR any fault word != 0
// 3. OR any warning word != 0
// 4. OR activeAlarms array has items

const state = msg.payload;

const runStateNormal = state.runStateRaw === 2;
const noFaults = state.faultWord1Raw === 0 && 
                 state.faultWord2Raw === 0 && 
                 state.faultWord3Raw === 0 && 
                 state.faultWord4Raw === 0;
const noWarnings = state.warningWord1Raw === 0 && 
                   state.warningWord2Raw === 0;
const noActiveAlarms = state.activeAlarms.length === 0;

// If everything is normal, don't send
if (runStateNormal && noFaults && noWarnings && noActiveAlarms) {
    // Check if we need to send "all clear" once
    const previousHadAlarm = flow.get("ias_previous_had_alarm") || false;

    if (previousHadAlarm) {
        // Send one "all clear" message
        flow.set("ias_previous_had_alarm", false);
        node.status({ fill: "green", shape: "dot", text: "All clear - sent" });
        return msg;
    } else {
        // Already sent all clear, don't spam
        node.status({ fill: "green", shape: "ring", text: "Normal - skipped" });
        return null;
    }
}

// There's an alarm/warning - send it
flow.set("ias_previous_had_alarm", true);

const alarmCount = state.activeAlarms.length;
const runStateText = {
    0: "standby",
    1: "selfcheck",
    2: "normal",
    3: "ALARM",
    4: "FAULT"
}[state.runStateRaw] || "unknown";

node.status({ 
    fill: state.runStateRaw >= 3 ? "red" : "yellow", 
    shape: "dot", 
    text: `${runStateText} - ${alarmCount} alarms` 
});

return msg;

// Store RPC response topic if present
if (msg.rpcResponseTopic) {
    flow.set("inv_rpc_response_topic", msg.rpcResponseTopic);
}

// Inverter run state
// 600: run state
// 0=standby, 1=selfcheck, 2=normal, 3=alarm, 4=fault

msg.baseAddr = 600;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 600,
    quantity: 1
};
return msg;

// Temperatures
// 640: DC transformer temp (0.1°C, offset 1000)
// 641: Heat sink temp (0.1°C)

msg.baseAddr = 640;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 640,
    quantity: 2
};
return msg;

// Grid side phase powers - LOW words
// 722: Grid A-phase power LOW (1W, S32)
// 723: Grid B-phase power LOW (1W, S32)
// 724: Grid C-phase power LOW (1W, S32)
// 725: Grid total power LOW (1W, S32)

msg.baseAddr = 722;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 722,
    quantity: 4
};
return msg;

// Grid side phase powers - HIGH words
// 787: Grid A-phase power HIGH (1W, S32)
// 788: Grid B-phase power HIGH (1W, S32)
// 789: Grid C-phase power HIGH (1W, S32)
// 790: Grid total power HIGH (1W, S32)

msg.baseAddr = 787;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 787,
    quantity: 4
};
return msg;

// Output phase voltages
// 727: Phase A voltage (0.1V)
// 728: Phase B voltage (0.1V)
// 729: Phase C voltage (0.1V)

msg.baseAddr = 727;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 727,
    quantity: 3
};
return msg;

// Output phase currents
// 730: Phase A current (0.01A, S16)
// 731: Phase B current (0.01A, S16)
// 732: Phase C current (0.01A, S16)

msg.baseAddr = 730;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 730,
    quantity: 3
};
return msg;

// Output phase powers - LOW words
// 733: Phase A power LOW (1W, S32)
// 734: Phase B power LOW (1W, S32)
// 735: Phase C power LOW (1W, S32)
// 736: Total active power LOW (1W, S32)
// 737: Total apparent power LOW (1W, S32)

msg.baseAddr = 733;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 733,
    quantity: 5
};
return msg;

// Output phase powers - HIGH words
// 791: Phase A power HIGH (1W, S32)
// 792: Phase B power HIGH (1W, S32)
// 793: Phase C power HIGH (1W, S32)
// 794: Total active power HIGH (1W, S32)
// 795: Total apparent power HIGH (1W, S32)

msg.baseAddr = 791;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 791,
    quantity: 5
};
return msg;

// Inverter output frequency
// 738: Inverter frequency (0.01Hz)

msg.baseAddr = 738;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 738,
    quantity: 1
};
return msg;

// AC Input Status
// 240: Gen_Grid_Signal (R/W register)
// bit0 = grid signal present
// bit1 = generator signal present

msg.baseAddr = 240;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 240,
    quantity: 1
};
return msg;

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    return null;
}

function s16(v) {
    if (!Number.isFinite(v)) return null;
    return (v & 0x8000) ? v - 0x10000 : v;
}

function s32(low, high) {
    const u = ((high & 0xFFFF) << 16) | (low & 0xFFFF);
    return (u & 0x80000000) ? u - 0x100000000 : u;
}

function mapRunState(code) {
    const states = { 0: "standby", 1: "selfcheck", 2: "normal", 3: "alarm", 4: "fault" };
    return states[code] || "unknown";
}

// RunState 600
if (baseAddr === 600) {
    flow.set("inv_part_runstate", { runState: mapRunState(data[0] || 0) });
}

// Temps 640-641
else if (baseAddr === 640) {
    const dcTransformerRaw = data[0] || 0;  // offset 1000
    const heatsinkRaw = data[1] || 0;
    flow.set("inv_part_temps", {
        dcTransformerTempC: Math.round((dcTransformerRaw - 1000) * 0.1 * 10) / 10,
        heatsinkTempC: Math.round(heatsinkRaw * 0.1 * 10) / 10
    });
}

// Grid Power Low 722-725
else if (baseAddr === 722) {
    flow.set("inv_part_grid_power_low", {
        phaseA: data[0] || 0,
        phaseB: data[1] || 0,
        phaseC: data[2] || 0,
        total: data[3] || 0
    });
}

// Grid Power High 787-790
else if (baseAddr === 787) {
    const low = flow.get("inv_part_grid_power_low");
    if (low) {
        flow.set("inv_part_grid_power", {
            phaseAPowerW: s32(low.phaseA, data[0]),
            phaseBPowerW: s32(low.phaseB, data[1]),
            phaseCPowerW: s32(low.phaseC, data[2]),
            totalActivePowerW: s32(low.total, data[3])
        });
    }
}

// Output Voltage 727-729
else if (baseAddr === 727) {
    flow.set("inv_part_voltage", {
        phaseAVoltageV: Math.round(data[0] * 0.1 * 10) / 10,
        phaseBVoltageV: Math.round(data[1] * 0.1 * 10) / 10,
        phaseCVoltageV: Math.round(data[2] * 0.1 * 10) / 10
    });
}

// Output Current 730-732
else if (baseAddr === 730) {
    flow.set("inv_part_current", {
        phaseACurrentA: Math.round(s16(data[0]) * 0.01 * 100) / 100,
        phaseBCurrentA: Math.round(s16(data[1]) * 0.01 * 100) / 100,
        phaseCCurrentA: Math.round(s16(data[2]) * 0.01 * 100) / 100
    });
}

// Output Power Low 733-737
else if (baseAddr === 733) {
    flow.set("inv_part_output_power_low", {
        phaseA: data[0] || 0,
        phaseB: data[1] || 0,
        phaseC: data[2] || 0,
        totalActive: data[3] || 0,
        totalApparent: data[4] || 0
    });
}

// Output Power High 791-795
else if (baseAddr === 791) {
    const low = flow.get("inv_part_output_power_low");
    if (low) {
        flow.set("inv_part_output_power", {
            phaseAPowerW: s32(low.phaseA, data[0]),
            phaseBPowerW: s32(low.phaseB, data[1]),
            phaseCPowerW: s32(low.phaseC, data[2]),
            totalActivePowerW: s32(low.totalActive, data[3]),
            totalApparentPowerVA: s32(low.totalApparent, data[4])
        });
    }
}

// Freq 738
else if (baseAddr === 738) {
    flow.set("inv_part_freq", {
        frequencyHz: Math.round((data[0] || 0) * 0.01 * 100) / 100
    });
}

// AC Input 240
else if (baseAddr === 240) {
    const signal = data[0] || 0;
    flow.set("inv_part_ac_input", {
        genGridSignalRaw: signal,
        gridSignalPresent: (signal & 0x01) !== 0,
        generatorSignalPresent: (signal & 0x02) !== 0
    });
}
else {
    return null;
}

// Assemble
const runstatePart = flow.get("inv_part_runstate");
const tempsPart = flow.get("inv_part_temps");
const gridPowerPart = flow.get("inv_part_grid_power");
const voltagePart = flow.get("inv_part_voltage");
const currentPart = flow.get("inv_part_current");
const outputPowerPart = flow.get("inv_part_output_power");
const freqPart = flow.get("inv_part_freq");
const acInputPart = flow.get("inv_part_ac_input");

if (!runstatePart || !tempsPart || !gridPowerPart || !voltagePart || 
    !currentPart || !outputPowerPart || !freqPart || !acInputPart) {
    return null;
}

const deviceId = msg.deviceId || global.get("DEVICE_ID") || env.get("DEVICE_ID") || "EC100";

const state = {
    kind: "InverterDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    runState: runstatePart.runState,

    output: {
        totalActivePowerW: outputPowerPart.totalActivePowerW,
        totalApparentPowerVA: outputPowerPart.totalApparentPowerVA,
