const writes = [];

// Register 160: remoteLock
if (params.remoteLock !== undefined) {
    const val = params.remoteLock === "locked" ? 0x0002 : 0x0000;
    writes.push({ register: 160, value: val, name: "Remote Lock" });
}

// Register 180: powerSwitch
if (params.powerSwitch !== undefined) {
    writes.push({ register: 180, value: params.powerSwitch, name: "Power Switch" });
}

// Register 181: factoryResetEnabled
if (params.factoryResetEnabled !== undefined) {
    const val = params.factoryResetEnabled ? 1 : 0;
    writes.push({ register: 181, value: val, name: "Factory Reset" });
}

// Register 183: islandProtectionEnabled
if (params.islandProtectionEnabled !== undefined) {
    const val = params.islandProtectionEnabled ? 1 : 0;
    writes.push({ register: 183, value: val, name: "Island Protection" });
}

if (writes.length === 0) {
    msg.operationType = 'read';
    return [null, msg];
}

// Store to GLOBAL context
global.set("ics_write_queue", writes);
global.set("ics_write_index", 0);
global.set("ics_write_results", []);
global.set("ics_write_rpc_topic", msg.rpcResponseTopic);

node.status({ fill: "blue", shape: "dot", text: `${writes.length} writes queued` });

return [msg, null];

const writes = global.get("ics_write_queue") || [];
const index = global.get("ics_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

const newMsg = {
    payload: {
        fc: 16,
        unitid: 1,
        address: current.register,
        quantity: 1,
        value: [current.value]
    },
    currentWrite: current,
    writeIndex: index
};

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return newMsg;

const writes = global.get("ics_write_queue") || [];
let index = global.get("ics_write_index") || 0;
const results = global.get("ics_write_results") || [];

// Record success
const current = writes[index];
if (current) {
    results.push({ 
        register: current.register, 
        name: current.name, 
        value: current.value, 
        success: true 
    });
    global.set("ics_write_results", results);
}

// Move to next
index++;
global.set("ics_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

// More writes?
if (index < writes.length) {
    return [{ doNext: true }, null];
}

// All done - go to read
const rpcTopic = global.get("ics_write_rpc_topic");

global.set("ics_write_queue", null);
global.set("ics_write_index", null);
global.set("ics_write_rpc_topic", null);

const finalMsg = {
    writeResult: {
        success: true,
        message: `Successfully wrote ${results.length} register(s)`,
        writes: results
    },
    rpcResponseTopic: rpcTopic
};

node.status({ fill: "green", shape: "dot", text: `All ${results.length} writes OK!` });

return [null, finalMsg];

const scenario = msg.testScenario || 'normal';
const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "TEST-INVERTER-001";

let runState = 2;  // 0=standby, 1=selfcheck, 2=normal, 3=alarm, 4=fault
let warningWord1 = 0;
let warningWord2 = 0;
let faultWord1 = 0;
let faultWord2 = 0;
let faultWord3 = 0;
let faultWord4 = 0;
const activeAlarms = [];

const now = new Date().toISOString();

switch(scenario) {
    case 'normal':
        // All zeros, run state = normal
        runState = 2;
        break;

    case 'warning_fan':
        // 653 Bit5: FAN_LOCKED - Fan warning
        runState = 3;  // alarm
        warningWord1 = 0x0020;  // Bit5 set (2006)
        activeAlarms.push({
            code: 2006,
            vendorCode: 5,
            severity: "warning",
            sourceDevice: "inverter",
            category: "fan",
            messageKey: "FAN_LOCKED",
            messageParams: {},
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        });
        break;

    case 'warning_grid':
        // 653 Bit12: Grid phase error - 电网相位错误
        runState = 3;  // alarm
        warningWord1 = 0x1000;  // Bit12 set
        activeAlarms.push({
            code: 653012,
            vendorCode: 12,
            severity: "warning",
            sourceDevice: "grid",
            category: "grid_quality",
            messageKey: "GRID_PHASE_WRONG",
            messageParams: {},
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        });
        break;

    case 'warning_battery':
        // 653 Bit2: BATTERY_COMM_FAIL - Battery communication fault
        runState = 3;  // alarm
        warningWord1 = 0x0004;  // Bit2 set (2003)
        activeAlarms.push({
            code: 2003,
            vendorCode: 2,
            severity: "warning",
            sourceDevice: "battery",
            category: "communication",
            messageKey: "BATTERY_COMM_FAIL",
            messageParams: {},
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        });
        break;

    case 'fault_multiple':
        // Multiple faults - realistic scenario
        runState = 4;  // fault

        // Warning 653 Bit5: FAN_LOCKED
        warningWord1 = 0x0020;
        activeAlarms.push({
            code: 2006,
            vendorCode: 5,
            severity: "warning",
            sourceDevice: "inverter",
            category: "fan",
            messageKey: "FAN_LOCKED",
            messageParams: {},
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        });

        // Warning 653 Bit3: INVERTER_TEMP_HIGH
        warningWord1 |= 0x0008;  // Also set Bit3
        activeAlarms.push({
            code: 2004,
            vendorCode: 3,
            severity: "warning",
            sourceDevice: "inverter",
            category: "over_temp",
            messageKey: "INVERTER_TEMP_HIGH",
            messageParams: {},
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        });

        // Fault 655 Bit10: INVERTER_OVER_TEMP
        faultWord1 = 0x0400;  // Bit10
        activeAlarms.push({
            code: 1011,
            vendorCode: 10,
            severity: "fault",
            sourceDevice: "inverter",
            category: "over_temp",
            messageKey: "INVERTER_OVER_TEMP",
            messageParams: {},
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        });
        break;
}

const state = {
    kind: "InverterAlarmState",
    timestampUtc: now,
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    runStateRaw: runState,
    warningWord1Raw: warningWord1,
    warningWord2Raw: warningWord2,
    faultWord1Raw: faultWord1,
    faultWord2Raw: faultWord2,
    faultWord3Raw: faultWord3,
    faultWord4Raw: faultWord4,

    activeAlarms: activeAlarms
};

msg.payload = state;
msg.topic = "v1/devices/me/telemetry";

node.status({ 
    fill: runState === 2 ? "green" : (runState === 3 ? "yellow" : "red"), 
    shape: "dot", 
    text: `${scenario}: RunState=${runState}, Alarms=${activeAlarms.length}` 
});

return msg;
